package com.yuyutian.mytools.gateway.service;
import com.yuyutian.mytools.gateway.config.GatewayProperties;import org.junit.jupiter.api.Test;import org.springframework.http.MediaType;import org.springframework.test.web.client.MockRestServiceServer;import org.springframework.web.client.RestTemplate;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.springframework.http.HttpMethod.GET;import static org.springframework.test.web.client.match.MockRestRequestMatchers.*;import static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;
class MessagingGatewayClientTest { @Test void shouldReturnSafeOwnerBoundMessages(){RestTemplate template=new RestTemplate();MockRestServiceServer server=MockRestServiceServer.bindTo(template).build();UUID id=UUID.randomUUID();server.expect(requestTo("http://messaging/internal/v1/inbound-messages?ownerId=55&limit=50")).andExpect(method(GET)).andExpect(header("Authorization","Bearer messaging-token")).andRespond(withSuccess("{\"items\":[{\"id\":\""+id+"\",\"ownerId\":55,\"channelType\":\"EMAIL\",\"externalMessageId\":\"private-id\",\"conversationKey\":\"private-thread\",\"sender\":\"sender@example.com\",\"subject\":\"Subject\",\"body\":\"Body\",\"receivedAt\":\"2026-08-24T00:00:00Z\",\"createdAt\":\"2026-08-24T00:00:00Z\",\"parts\":[]}],\"nextAfterId\":null}",MediaType.APPLICATION_JSON));var page=new MessagingGatewayClient(template,properties()).list(55L,null,50,"correlation");assertThat(page.items()).hasSize(1);assertThat(page.items().getFirst().toString()).doesNotContain("private-id","private-thread");server.verify();}
 @Test void shouldCreateSafeOwnerBoundAttachmentJob(){RestTemplate template=new RestTemplate();MockRestServiceServer server=MockRestServiceServer.bindTo(template).build();UUID messageId=UUID.randomUUID(),partId=UUID.randomUUID(),jobId=UUID.randomUUID();server.expect(requestTo("http://messaging/internal/v1/inbound-messages/"+messageId+"/parts/"+partId+"/download?ownerId=55")).andExpect(method(org.springframework.http.HttpMethod.POST)).andRespond(withSuccess("{\"id\":\""+jobId+"\",\"messageId\":\""+messageId+"\",\"partId\":\""+partId+"\",\"status\":\"ACCEPTED\",\"taskId\":\""+UUID.randomUUID()+"\",\"downloadRequestId\":null,\"lastErrorCode\":null,\"createdAt\":\"2026-08-24T00:00:00Z\",\"updatedAt\":\"2026-08-24T00:00:00Z\"}",MediaType.APPLICATION_JSON));var job=new MessagingGatewayClient(template,properties()).createAttachment(55L,messageId,partId,"correlation");assertThat(job.id()).isEqualTo(jobId);assertThat(job.toString()).doesNotContain("taskId","downloadRequestId");server.verify();}
 private GatewayProperties properties(){return new GatewayProperties(GatewayProperties.IdentityMode.LEGACY,false,false,Set.of(),false,Set.of(),false,Set.of(),"http://mytools","http://identity","http://reader","http://drive","http://download","gateway-token","identity-token","reader-token","drive-token","download-token",1000,3000,false,"","",true,"http://messaging","messaging-token");}}
